{"path":"/tmp/verify_workbook.py","content":"from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

path = '/root/output/result.xlsx'
wb = load_workbook(path, data_only=False)
ws = wb['Task']
print('Workbook:', path)
print('Sheet names:', wb.sheetnames)
print('\nModified-cell formulas:')
for rng in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']:
    print(f'Range {rng}:')
    for row in ws[rng]:
        print('  ' + ', '.join(f'{cell.coordinate}={cell.value!r}' for cell in row))

bad_literals = {'#NAME?', '#REF!', '#VALUE!'}
found = []
for ws2 in wb.worksheets:
    for row in ws2.iter_rows():
        for cell in row:
            if cell.value in bad_literals:
                found.append((ws2.title, cell.coordinate, cell.value))
print('\nLiteral error string check:', 'PASS - none found' if not found else f'FAIL - {found}')

# Additional syntax/constraint checks over the cells we modified.
issues = []
for rng in ['H12:L17','H19:L24','H26:L31']:
    for row in ws[rng]:
        for cell in row:
            v = cell.value
            if not (isinstance(v, str) and v.startswith('=INDEX(') and 'MATCH(' in v):
                issues.append((cell.coordinate, 'lookup formula is not INDEX/MATCH', v))
for rng in ['H42:L47']:
    for row in ws[rng]:
        for cell in row:
            v = cell.value
            if isinstance(v, str) and ('PERCENTILE.INC' in v or 'PERCENTILE.EXC' in v):
                issues.append((cell.coordinate, 'wrong percentile function', v))
for rng in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']:
    for row in ws[rng]:
        for cell in row:
            if not (isinstance(cell.value, str) and cell.value.startswith('=')):
                issues.append((cell.coordinate, 'modified cell does not contain a formula', cell.value))
print('Formula constraint check:', 'PASS' if not issues else f'FAIL - {issues}')
","cross_profile":false}
